ALTER TABLE public.forum_replies ADD COLUMN attachment_path text, ADD COLUMN attachment_type text CHECK (attachment_type IN ('image','video','audio')), ADD COLUMN attachment_name text;
ALTER TABLE public.forum_replies ADD CONSTRAINT forum_reply_media_complete CHECK ((attachment_path IS NULL AND attachment_type IS NULL AND attachment_name IS NULL) OR (attachment_path IS NOT NULL AND attachment_type IS NOT NULL AND attachment_name IS NOT NULL AND length(attachment_name) BETWEEN 1 AND 255));
CREATE FUNCTION public.validate_forum_media() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.attachment_path IS NOT NULL THEN IF split_part(NEW.attachment_path, '/', 1) <> NEW.user_id::text OR NOT EXISTS (SELECT 1 FROM storage.objects WHERE bucket_id = 'forum-media' AND name = NEW.attachment_path) THEN RAISE EXCEPTION 'Pièce jointe invalide'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_forum_media BEFORE INSERT OR UPDATE OF attachment_path, attachment_type, user_id ON public.forum_replies FOR EACH ROW EXECUTE FUNCTION public.validate_forum_media();
CREATE POLICY "Forum media upload own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'forum-media' AND (storage.foldername(name))[1] = auth.uid()::text AND lower(coalesce(metadata->>'mimetype','')) IN ('image/jpeg','image/png','image/webp','image/gif','video/mp4','video/webm','video/quicktime','audio/webm','audio/ogg','audio/mp4','audio/mpeg','audio/wav') AND (metadata->>'size')::bigint <= 52428800);
CREATE POLICY "Forum media authenticated read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'forum-media' AND ((storage.foldername(name))[1] = auth.uid()::text OR EXISTS (SELECT 1 FROM public.forum_replies r WHERE r.attachment_path = name)));
CREATE POLICY "Forum media owner delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'forum-media' AND ((storage.foldername(name))[1] = auth.uid()::text OR public.has_role(auth.uid(), 'admin')));